16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.samples.petclinic.model.Owner;
19	import org.springframework.samples.petclinic.repository.OwnerRepository;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Produces the customer code assigned to a new {@link Owner}.
24	 *
25	 * <p>The code is formatted {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the
26	 * upper-cased first three letters of the owner's last name and {@code NNNN} is a
27	 * 4-digit zero-padded global sequence equal to one more than the current number
28	 * of owners (e.g. {@code 'SMI-0007'}).
29	 */
30	@Component
31	public class CustomerCodeGenerator {
32	
33	    private static final int PREFIX_LENGTH = 3;
34	
35	    private final OwnerRepository ownerRepository;
36	
37	    public CustomerCodeGenerator(OwnerRepository ownerRepository) {
38	        this.ownerRepository = ownerRepository;
39	    }
40	
41	    /**
42	     * Generate the customer code for the given owner based on its last name and
43	     * the current owner count.
44	     *
45	     * @param owner the owner being registered
46	     * @return the {@code '<LAST3>-<NNNN>'} customer code
47	     */
48	    public String generate(Owner owner) {
49	        long sequence = ownerRepository.count() + 1;
50	        return String.format("%s-%04d", prefix(owner.getLastName()), sequence);
51	    }
52	
53	    /** The upper-cased first three letters of the given last name. */
54	    private static String prefix(String lastName) {
55	        StringBuilder prefix = new StringBuilder(PREFIX_LENGTH);
56	        for (int i = 0; i < lastName.length() && prefix.length() < PREFIX_LENGTH; i++) {
57	            char c = lastName.charAt(i);
58	            if (Character.isLetter(c)) {
59	                prefix.append(Character.toUpperCase(c));
60	            }
61	        }
62	        return prefix.toString();
63	    }
64	}
