27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    /**
70	     * Default the registration date to the server's current date when none was
71	     * supplied at creation time.
72	     */
73	    @PrePersist
74	    private void defaultRegistrationDate() {
75	        if (this.registrationDate == null) {
76	            this.registrationDate = LocalDate.now();
77	        }
78	    }
79	
80	    public String getAddress() {
81	        return this.address;
82	    }
83	
84	    public void setAddress(String address) {
85	        this.address = address;
86	    }
87	
88	    public String getCity() {
89	        return this.city;
90	    }
91	
92	    public void setCity(String city) {
93	        this.city = city;
94	    }
95	
96	    public String getTelephone() {
97	        return this.telephone;
98	    }
99	
100	    public void setTelephone(String telephone) {
101	        this.telephone = telephone;
102	    }
103	
104	    public String getEmail() {
105	        return this.email;
106	    }
107	
108	    public void setEmail(String email) {
109	        this.email = email;
110	    }
111	
112	    public LocalDate getRegistrationDate() {
113	        return this.registrationDate;
114	    }
115	
116	    public void setRegistrationDate(LocalDate registrationDate) {
117	        this.registrationDate = registrationDate;
118	    }
119	
120	    public String getCustomerCode() {
121	        return this.customerCode;
122	    }
123	
124	    public void setCustomerCode(String customerCode) {
125	        this.customerCode = customerCode;
126	    }
127	
128	    /**
129	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
130	     * where {@code YY} is the last two digits of the {@link #registrationDate}
131	     * year (e.g. {@code "SMI-0007-M26"}). Derived from the owner's own fields.
132	     */
133	    public String getMembershipNumber() {
134	        if (this.customerCode == null || this.registrationDate == null) {
135	            return null;
136	        }
137	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
138	    }
139	
140	    public String getHouseholdId() {
141	        return this.householdId;
142	    }
143	
144	    public void setHouseholdId(String householdId) {
145	        this.householdId = householdId;
146	    }
147	
148	    /**
149	     * The owner's membership tier, derived from the owner's own fields. Returns
150	     * {@code "SILVER"} when the owner has no namesakes and a contact email on
151	     * file, and {@code "BRONZE"} otherwise.
152	     */
153	    public String getMembershipTier() {
154	        boolean hasEmail = this.email != null && !this.email.isEmpty();
155	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
156	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
157	    }
158	
159	    public Integer getNamesakeCount() {
160	        return this.namesakeCount;
161	    }
162	
163	    public void setNamesakeCount(Integer namesakeCount) {
164	        this.namesakeCount = namesakeCount;
165	    }
166	
167	    protected Set<Pet> getPetsInternal() {
168	        if (this.pets == null) {
169	            this.pets = new HashSet<>();
170	        }
171	        return this.pets;
172	    }
173	
174	    protected void setPetsInternal(Set<Pet> pets) {
175	        this.pets = pets;
176	    }
177	
178	    public List<Pet> getPets() {
179	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
180	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
181	        return Collections.unmodifiableList(sortedPets);
182	    }
183	
184	    public void setPets(List<Pet> pets) {
185	        this.pets = new HashSet<>(pets);
186	    }
187	
188	    public void addPet(Pet pet) {
189	        getPetsInternal().add(pet);
190	        pet.setOwner(this);
191	    }
192	
193	    /**
194	     * Return the Pet with the given name, or null if none found for this Owner.
195	     *
196	     * @param name to test
197	     * @return true if pet name is already in use
198	     */
199	    public Pet getPet(String name) {
200	        return getPet(name, false);
201	    }
202	
203	    /**
204	     * Return the Pet with the given name, or null if none found for this Owner.
205	     *
206	     * @param name to test
207	     * @return true if pet name is already in use
208	     */
209	    public Pet getPet(String name, boolean ignoreNew) {
210	        name = name.toLowerCase();
211	        for (Pet pet : getPetsInternal()) {
212	            if (!ignoreNew || !pet.isNew()) {
213	                String compName = pet.getName();
214	                compName = compName.toLowerCase();
215	                if (compName.equals(name)) {
216	                    return pet;
217	                }
218	            }
219	        }
220	        return null;
221	    }
222	
223	    public Pet getPet(Integer petId) {
224	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
225	    }
226	
227	    @Override
228	    public String toString() {
229	        return new ToStringCreator(this)
230	
231	            .append("id", this.getId())
232	            .append("new", this.isNew())
233	            .append("lastName", this.getLastName())
234	            .append("firstName", this.getFirstName())
235	            .append("address", this.address)
236	            .append("city", this.city)
237	            .append("telephone", this.telephone)
238	            .append("email", this.email)
239	            .toString();
240	    }
241	}
