266	    @Override
267	    @Transactional(readOnly = true)
268	    public Collection<Owner> findOwnersInHousehold(String lastName, String address) throws DataAccessException {
269	        String targetLastName = TextNormalizer.normalizeForComparison(lastName);
270	        String targetAddress = TextNormalizer.normalizeForComparison(address);
271	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
272	            .filter(owner -> TextNormalizer.normalizeForComparison(owner.getLastName()).equals(targetLastName))
273	            .filter(owner -> TextNormalizer.normalizeForComparison(owner.getAddress()).equals(targetAddress))
274	            .collect(Collectors.toList());
275	    }
276	
277	    @Override
278	    @Transactional
279	    public String joinHousehold(Owner owner, Collection<Owner> existingMembers) throws DataAccessException {
280	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
281	        owner.setHouseholdId(householdId);
282	        for (Owner member : existingMembers) {
283	            if (!householdId.equals(member.getHouseholdId())) {
284	                member.setHouseholdId(householdId);
285	                ownerRepository.save(member);
286	            }
287	        }
288	        return householdId;
289	    }
290	
291	    @Override
292	    @Transactional(readOnly = true)
293	    public Collection<Visit> findVisitsByPetId(int petId) {
294	        return visitRepository.findByPetId(petId);
295	    }
296	
297	    @Override
298	    @Transactional(readOnly = true)
299	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
300	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
301	    }
302	
303	    private <T> T findEntityById(Supplier<T> supplier) {
304	        try {
305	            return supplier.get();
306	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
307	            // Just ignore not found exceptions for Jdbc/Jpa realization
308	            return null;
309	        }
310	    }
311	
312	}
